insert into public.story_chapters (slug, kicker, title, body, badge, photo_hint, photo_url, photo_alt, link_href, link_label, position)
select * from (values
  ('the-idea', 'Kuakata', 'An idea by the sea', 'On a departmental trip to Kuakata, Late Dr. Ali Shihab Sabbir Sir, then Dean of the School of Engineering and Computer Science, imagined a place where CSE students could grow beyond the classroom.', 'The idea', 'Dr. Sabbir with students on the Kuakata trip', '/about/sabbir/smiling.jpg', 'Dr. Ali Shihab Sabbir, smiling, beside a window', '/about/dr-ali-shihab-sabbir', 'In memory of Dr. Sabbir', 0),
  ('the-name', 'যুক্তি', 'A name that means logic', 'He proposed the name “JUKTI”, meaning logic: a fundamental concept in computer science, and the way of thinking the club would stand for.', 'JUKTI = Logic', 'An early JUKTI banner or the first logo sketch', null, '', null, null, 1),
  ('founded', '2014', 'The club is founded', 'JUKTI, the Club of Computer Science and Engineering at IUB, was established in 2014 under Founding Faculty Advisor Raihan Bin Rafique Sir and Founding President Rakib Hassan Rocky, around three guiding principles: skill, networking and knowledge.', 'Est. 2014', 'The founding committee, 2014', null, '', null, null, 2),
  ('programming-contest-2015', '2015', 'Learning by competing', 'On 4 July 2015, JUKTI and the Department of CSE ran the Intra-IUB Programming Contest: 24 teams from CSE and EEE, 13 problems, five hours. It capped a programming training camp that had started that March.', 'Intra-IUB Contest', 'Teams at the 2015 Intra-IUB Programming Contest', null, '', null, null, 3),
  ('first-national-event', '2016', 'Our first national stage', 'One of the club’s early milestones: organizing the NASA Space Apps Challenge at IUB in 2016, JUKTI’s first national-level event.', 'Space Apps 2016', 'Participants at NASA Space Apps Challenge 2016, IUB', null, '', null, null, 4),
  ('industry-visit-2026', '2026', 'Beyond the classroom', 'On 16 July 2026, JUKTI took 56 CSE students and two faculty members to Walton Digi-Tech Industries in Kaliakoir, Gazipur: through the display centre, the data centre and the circuit-board production line.', 'Industry Visit 2026', 'The group at Walton Digi-Tech, July 2026', null, '', null, null, 5),
  ('today', 'Today', 'The largest CSE community at IUB', 'JUKTI runs workshops, contests and events, community service and sports, and keeps a growing alumni network close: graduates in software, data science, research and business who come back to mentor the next batch.', 'Today', 'A recent JUKTI event, full house', null, '', null, null, 6)
) as v(slug, kicker, title, body, badge, photo_hint, photo_url, photo_alt, link_href, link_label, position)
where not exists (select 1 from public.story_chapters);

